const fs = await import('node:fs/promises');
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const doc = await fs.readFile(P2+"\\大学生人群商机-深挖.md","utf8");
// 提取所有引用来源
const srcs = [...doc.matchAll(/来源[:：]\s*([^\n]+)/g)].map(m=>m[1].trim());
const links = [...doc.matchAll(/\[\[([^\]]+)\]\]|(https?:\/\/[^\s\)]+)/g)].map(m=>m[1]||m[2]);
// 找关键数字上下文
const idx = doc.indexOf("3.5");
const ctx = idx>0 ? doc.slice(Math.max(0,idx-600), idx+400) : "";
return { chars: doc.length, sources: srcs, links: links.slice(0,10), ctx35000: ctx };
